b=pathlib.Path(__file__).resolve().parent;repo=b.parents[3];control=repo.parents[1]/('outputs/qwen7b-warmup-20261019/'+args.control+'-control.py');r=subprocess.run([sys.executable,str(control),str(b/'read-mse-agent.py'),'--timeout','35'],stdout=subprocess.PIPE,stderr=subprocess.PIPE,text=True)
